extern "C" {
__device__ __forceinline__ float bsum(float s, float* out){
  __shared__ float red[32];
  for(int o=16;o>0;o>>=1) s+=__shfl_xor_sync(0xffffffff,s,o);
  int w=threadIdx.x>>5, l=threadIdx.x&31;
  __syncthreads();
  if(l==0) red[w]=s;
  __syncthreads();
  if(threadIdx.x==0){ float t=0; for(int i=0;i<(blockDim.x>>5);i++) t+=red[i]; out[blockIdx.x]=t; }
  return s;
}
// (a) plain LDG.128, tile = 256 thr * U float4
__global__ void __launch_bounds__(256) rd_plain(const float4* W, float* out, long ntiles){
  float s=0;
  for(long t=blockIdx.x; t<ntiles; t+=gridDim.x){
    const float4* p=W+t*(256*%(U)d)+threadIdx.x; float4 v[%(U)d];
    #pragma unroll
    for(int j=0;j<%(U)d;j++) v[j]=p[j*256];
    #pragma unroll
    for(int j=0;j<%(U)d;j++) s+=v[j].x+v[j].y+v[j].z+v[j].w;
  }
  bsum(s,out);
}
// (b) evict_first via createpolicy
__global__ void __launch_bounds__(256) rd_ef(const float4* W, float* out, long ntiles){
  unsigned long long pol; asm volatile("createpolicy.fractional.L2::evict_first.b64 %%0, 1.0;":"=l"(pol));
  float s=0;
  for(long t=blockIdx.x; t<ntiles; t+=gridDim.x){
    const float4* p=W+t*(256*%(U)d)+threadIdx.x; float4 v[%(U)d];
    #pragma unroll
    for(int j=0;j<%(U)d;j++) asm volatile("ld.global.L2::cache_hint.v4.f32 {%%0,%%1,%%2,%%3}, [%%4], %%5;":"=f"(v[j].x),"=f"(v[j].y),"=f"(v[j].z),"=f"(v[j].w):"l"(p+j*256),"l"(pol));
    #pragma unroll
    for(int j=0;j<%(U)d;j++) s+=v[j].x+v[j].y+v[j].z+v[j].w;
  }
  bsum(s,out);
}
// (d) 256-bit loads, tile = 256 thr * U * 32B
__global__ void __launch_bounds__(256) rd_256(const float* W, float* out, long ntiles){
  float s=0;
  for(long t=blockIdx.x; t<ntiles; t+=gridDim.x){
    const float* p=W+t*(256*8*%(U)d)+threadIdx.x*8; float v[%(U)d][8];
    #pragma unroll
    for(int j=0;j<%(U)d;j++){
      asm volatile("ld.global.v8.f32 {%%0,%%1,%%2,%%3,%%4,%%5,%%6,%%7}, [%%8];":"=f"(v[j][0]),"=f"(v[j][1]),"=f"(v[j][2]),"=f"(v[j][3]),"=f"(v[j][4]),"=f"(v[j][5]),"=f"(v[j][6]),"=f"(v[j][7]):"l"(p+j*256*8));
    }
    #pragma unroll
    for(int j=0;j<%(U)d;j++)
      #pragma unroll
      for(int k=0;k<8;k++) s+=v[j][k];
  }
  bsum(s,out);
}
// (c) 1-D bulk ring
#define ST %(ST)d
#define CHB %(CHB)d
__global__ void __launch_bounds__(128) rd_bulk(const char* W, float* out, int nchunks, int hint){
