__global__ void rd_flush(const float4* a, float* out, long n4){
  float s=0; for(long i=blockIdx.x*256L+threadIdx.x;i<n4;i+=gridDim.x*256L){ float4 v=a[i]; s+=v.x+v.y+v.z+v.w; }
  if(s==1234.5f) out[0]=s;
}
