    #pragma unroll
    for(int j=0;j<2;j++) asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(v[j].x),"=f"(v[j].y),"=f"(v[j].z),"=f"(v[j].w):"l"(p+j*256),"l"(pf));
    #pragma unroll
    for(int j=0;j<2;j++) s+=v[j].x+v[j].y+v[j].z+v[j].w;
  }
  float4 val=make_float4(s,s,s,s);
  for(int i=blockIdx.x*256+threadIdx.x;i<no4;i+=gridDim.x*256){
    if(mode==0) o[i]=val;
    else asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;"::"l"(o+i),"f"(s),"f"(s),"f"(s),"f"(s),"l"(pol));
  }
}
}
'''
k={n:cuda_kernel(SRC,n) for n in ['rd_plain','rd_ef','rd_ef256','rd_ef_wr']}
dev='cuda'
W=torch.randn(NF,device=dev); out=torch.zeros(4096,device=dev)
