    if(hint) asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1], %2, [%3], %4;"::"r"(dst),"l"(W+c*CHB),"r"(CHB),"r"(bar),"l"(pol):"memory");
    else asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];"::"r"(dst),"l"(W+c*CHB),"r"(CHB),"r"(bar):"memory");
  };
  if(tid==0) for(int j=0;j<ST&&j<n;j++) issue(j);
  float s=0;
  for(int j=0;j<n;j++){
    int st=j%ST; unsigned bar=(unsigned)__cvta_generic_to_shared(&full[st]); unsigned par=(j/ST)&1;
    asm volatile("{\n.reg .pred p;\nW%=:\nmbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1;\n@!p bra W%=;\n}"::"r"(bar),"r"(par):"memory");
    const float4* q=(const float4*)(sm+st*CHB);
    for(int i=tid;i<CHB/16;i+=128){ float4 v=q[i]; s+=v.x+v.y+v.z+v.w; }
    __syncthreads();
    if(tid==0 && j+ST<n) issue(j+ST);
  }
  bsum(s,out);
}
__global__ void __launch_bounds__(256) scatter6(const float4* src, float4* const* o, int B){
  long total=(long)B*4608; long i=(long)blockIdx.x*256+threadIdx.x; if(i>=total) return;
  int b=i/4608, n4=i-(long)b*4608; int c=n4/768, j=n4-c*768;
  o[c][(long)b*768+j]=src[i];
}
}
